  'quentinnguyen.localize@gmail.com','therese.svardsten@gmail.com'
]);
const PSEUDO = new Set(['pst','ps','cus','pt_old']);

function isEmpty(t) {
  if (t === null || t === undefined) return true;
  if (typeof t === 'string') {
    const s = t.trim();
    if (!s) return true;
    if (s.startsWith('{') || s.startsWith('[')) {
      try { return isEmpty(JSON.parse(s)); } catch (e) { return false; }
    }
    return false;
  }
  if (typeof t === 'object') {
    const vals = Object.values(t);
    if (!vals.length) return true;
    return vals.every(v => isEmpty(v));
  }
  return false;
}

const body = $input.first().json.body || $input.first().json;
if (!Array.isArray(body.keys)) {
  throw new Error('No keys array: ' + JSON.stringify(body).slice(0, 300));
}

const buckets = {};
const empties = {};
let keysSeen = 0;

for (const k of body.keys) {
  keysSeen += 1;
  const trs = Array.isArray(k.translations) ? k.translations : [];
  const emptyLocales = [];
  for (const tr of trs) {
    const iso = tr.language_iso;
    if (!iso || PSEUDO.has(iso)) continue;
    if (!buckets[iso]) {
      buckets[iso] = { locale: iso, keys: 0, untranslated: 0, ai: 0, mt: 0, tm: 0,
        linguist: 0, other_editor: 0, linguist_touched: 0,
        machine_status_but_linguist_edit: 0, reviewed: 0, unverified: 0, authors: {} };
    }
    const r = buckets[iso];
    r.keys += 1;
    if (tr.is_reviewed) r.reviewed += 1;
    if (tr.is_unverified) r.unverified += 1;

    const titles = (tr.custom_translation_statuses || []).map(s => String(s.title || '').toUpperCase());
    const hasAI = titles.some(t => t.startsWith('AI'));
    const hasMT = titles.some(t => t === 'MT' || t.startsWith('MT_') || t.startsWith('MT '));
    const hasTM = titles.some(t => t.includes('TM'));
    const email = String(tr.modified_by_email || '').toLowerCase().trim();
    const byLinguist = LINGUISTS.has(email);

    if (isEmpty(tr.translation)) { r.untranslated += 1; emptyLocales.push(iso); continue; }
    r.authors[email || '(none)'] = (r.authors[email || '(none)'] || 0) + 1;
    if (byLinguist) r.linguist_touched += 1;
    if ((hasAI || hasMT) && byLinguist) r.machine_status_but_linguist_edit += 1;
    if (hasAI) { r.ai += 1; continue; }
    if (hasMT) { r.mt += 1; continue; }
    if (hasTM) { r.tm += 1; continue; }
    if (byLinguist) { r.linguist += 1; continue; }
    r.other_editor += 1;
  }
  if (emptyLocales.length) {
    const kn = k.key_name;
    const name = (kn && typeof kn === 'object') ? (kn.web || kn.other || kn.ios || kn.android || JSON.stringify(kn)) : String(kn);
    empties[name] = emptyLocales.join(',');
  }
}

return Object.values(buckets).map(r => ({ json: Object.assign({
  project_id: src.project_id,
  project: src.name,
  product: src.product,
  page: src.page,
  keys_on_page: keysSeen,
  empty_keys: empties
}, r) }));
